cat > /tmp/fuzz.c <<'EOF'
#include "collector.h"
#include "epic_clean.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int emitted;
static int emit_cb(void *user,int rank,const uint8_t *frame,size_t len)
{
    (void)user;(void)rank;(void)frame;(void)len;
    emitted++;
    return 1;
}

static uint32_t rnd_state=12345;
static uint32_t rnd(void){ rnd_state=rnd_state*1103515245u+12345u; return rnd_state>>8; }

int main(void)
{
    uint8_t frame[4200];
    for(int trial=0;trial<200;trial++){
        collector_t *c=collector_open(rnd()%6,2+(rnd()%2),rnd()%4,1+rnd()%64,1+rnd()%64,
                                     1+rnd()%32,rnd()%(1u<<24),emit_cb,NULL);
        if(!c)return 1;
        for(int i=0;i<400;i++){
            size_t len=rnd()%600;
            for(size_t j=0;j<len;j++)frame[j]=(uint8_t)rnd();
            /* half the time build a plausible frame */
            if(i%2==0 && len>=58){
                int rank=rnd()%4;
                size_t plen=4*(1+rnd()%16);
                if(len<58+plen)continue;
                uint8_t body[4096];
                for(size_t j=0;j<plen;j++)body[j]=(uint8_t)rnd();
                size_t n=epic_build_roce_data_raw(frame+200,sizeof(frame)-200,NULL,NULL,0,0,0,0,0,0,body,plen);
                (void)n;
            }
            collector_ingress(c,(int)(rnd()%4),frame,len);
        }
        collector_flush(c);
        collector_retry(c,(int)(rnd()%4));
        uint64_t st[32];collector_state(c,st);uint64_t h=collector_digest(c);
        if(st[30]||st[31]){fprintf(stderr,"counter %llu\n",(unsigned long long)st[30]);return 2;}
        collector_close(c);
    }
    printf("fuzz done, emitted=%d\n",emitted);
    return 0;
}
EOF
cd /tmp && gcc -std=c11 -O1 -g -fsanitize=address,undefined -static-libasan -fno-omit-frame-pointer -I/workspace/project/include /tmp/fuzz.c /workspace/project/src/roce_packet.c /workspace/project/src/star4_switch.c -o /tmp/fuzz 2>&1 | tail -3; ls -la /tmp/fuzz 2>/dev/null && /tmp/fuzz 2>&1 | tail -20
